# -*- coding: utf-8 -*-
"""Generate design-only innovation and trust-validation contracts for frontier capabilities."""
import argparse,json
from pathlib import Path
from orchestrator import atomic_write,digest
from jsonschema import Draft4Validator
ROOT=Path(__file__).resolve().parents[1]
DESIGNS={
'jaxpr_lowering':('Translate closed JAX jaxpr into typed IR with primitive, shape, effect and transformation provenance; preserve unsupported primitives as explicit proof gaps.', ['jaxpr, avals, effects, sharding metadata'],['typed IR plus lowering receipt'],['pure function semantics','shape/dtype preservation','effect/sharding preservation'], [('jaxpr_unit','Compare primitive-by-primitive execution against JAX on frozen inputs','all outputs and gradients within declared tolerance'),('effect_audit','Check random/state/control-flow effects are preserved or blocked','no effect silently erased')], ['dynamic Python behavior outside jaxpr','unsupported effect or primitive'], ['frozen JAX version','jaxpr text hash','reference outputs','primitive-level evidence']),
'autodiff_backprop':('Design a differentiable IR with explicit primal, tangent, cotangent and optimizer-state edges so training claims are inspectable.', ['primal graph, loss, parameter/state leaves'],['forward output, gradients, optimizer transition'],['gradient shape','finite gradient policy','optimizer state ownership'], [('finite_difference','Compare gradients on bounded perturbations','relative error below task threshold'),('second_order_or_directional','Check directional derivative on representative paths','all declared trainable leaves covered')], ['nondifferentiable custom op','silent stop_gradient','state update outside receipt'], ['framework version','gradient tape/jaxpr/autograd trace','seed and loss definition','gradient comparison receipt']),
'conv_recurrent_custom_ops':('Represent convolution, recurrence and custom kernels as contracts with layout, boundary, state and derivative semantics before implementation.', ['tensor layout, kernel/state, boundary conditions'],['output tensor, next state, gradients'],['layout contract','causality/state transition','padding/boundary semantics'], [('shape_reference','Compare output shapes and boundary cases','all edge cases agree'),('state_replay','Replay recurrent state transitions','same state hash and outputs')], ['implicit padding','hidden mutable state','custom op without derivative'], ['source implementation','equation/kernel reference','boundary tests','state transition trace']),
'cuda_measurement':('Separate lowering design from measurement: compile a reviewed kernel path and collect synchronized latency, memory and occupancy evidence.', ['typed IR, device, dtype, workload'],['kernel artifact, timing samples, memory samples'],['synchronization policy','warmup/repetition','device identity'], [('cuda_correctness','Compare CUDA outputs with CPU/reference','declared tolerance passes'),('measurement_repeatability','Repeat with fixed environment','variance and sample count meet threshold')], ['async timing without sync','cross-device comparison','allocator cache ambiguity'], ['CUDA/toolkit/driver versions','kernel source or compiler receipt','synchronization code','raw profiler output']),
'rank5_plus':('Generalize shape algebra to rank-N tensors with named axes and layout constraints, keeping element count, broadcasting and contraction explicit.', ['rank-N shape, named axes, layout'],['rank-N output and layout'],['axis identity','layout legality','bounded memory estimate'], [('shape_property','Property-test random legal shapes','shape and element count invariant'),('layout_roundtrip','Round-trip transpose/reshape/layout transforms','no silent axis permutation')], ['implicit broadcasting','unbounded memory','unknown layout conversion'], ['shape trace','axis names','memory budget','property-test receipt']),
'paper_to_fact':('Convert papers and code into provenance-linked architecture facts through claim extraction, evidence spans, contradiction tracking and human review.', ['paper/code snapshots, claim candidates'],['fact graph, uncertainty graph, review queue'],['source hash','evidence span','fact/inference/proposal separation'], [('span_check','Validate every fact against source span','no unsupported fact released'),('contradiction_check','Compare paper/code/experiments','conflicts remain explicit')], ['abstract-only inference','team attribution without evidence','AI draft marked as human gold'], ['paper snapshot hash','code commit hash','line/page spans','reviewer decision and rationale'])}
def build_design(design_id='frontier-neural-capabilities-v1'):
 caps=[]
 for cid,(hyp,inputs,outputs,invariants,gates,fails,evidence) in DESIGNS.items():
  caps.append({'id':cid,'status':'design_only','innovation_hypothesis':hyp,'architecture_contract':{'inputs':inputs,'outputs':outputs,'state':outputs,'invariants':invariants},'validation_gates':[{'id':gid,'test':test,'pass_condition':cond,'artifact':'validation_receipt.json'} for gid,test,cond in gates],'failure_conditions':fails,'evidence_requirements':evidence,'design_notes':['This artifact is a design and validation contract; it does not claim the capability is implemented or validated.']})
 return {'schema_version':'1.0','design_id':design_id,'capabilities':caps,'trust_policy':{'facts':'Require source snapshot, hash and precise evidence span.','inferences':'Label derivations and preserve assumptions.','proposals':'Treat innovations as hypotheses until experiments pass.','release_rule':'Never promote design_only to validated without all gates, replayable receipts and explicit unresolved questions.'}}
def validate_design(record):
 schema=json.loads((ROOT/'assets/frontier-capability-design.schema.json').read_text(encoding='utf8'));errors=list(Draft4Validator(schema).iter_errors(record))
 if errors:raise ValueError('Frontier design: '+errors[0].message)
 if len({c['id'] for c in record['capabilities']})!=6:raise ValueError('All six frontier capability designs are required')
 return record
def main():
 p=argparse.ArgumentParser();p.add_argument('cmd',choices=['generate','validate']);p.add_argument('path',nargs='?');p.add_argument('-o','--output');a=p.parse_args()
 try:
  record=build_design() if a.cmd=='generate' else validate_design(json.loads(Path(a.path).read_text(encoding='utf8')))
  if a.cmd=='generate':atomic_write(a.output,record)
  print(json.dumps({'status':'valid','design_id':record['design_id'],'capabilities':len(record['capabilities']),'sha256':digest(record)}))
 except (ValueError,OSError,KeyError) as exc:p.error(str(exc))
if __name__=='__main__':main()
